SELECT ROUND(SUM(CASE WHEN dc.member_level = '黄金' THEN fo.order_amount ELSE 0 END) / SUM(fo.order_amount) * 100, 2) AS gold_member_amount_percentage
FROM fact_order fo
LEFT JOIN dim_customer dc ON fo.customer_id = dc.customer_id;

SELECT AVG(CASE WHEN order_amount > avg_order_amount THEN 1 ELSE 0 END) AS above_avg_order_ratio
FROM (
    SELECT order_amount, AVG(order_amount) OVER () AS avg_order_amount
    FROM fact_order
) AS t;
